  }
  if (JSON.stringify(normalized).length > 96_000) {
    throw new GatewayError(
      400,
      "invalid_request_error",
      "Questions exceed the context budget.",
      "questions_too_large",
    );
  }
  const ids = Object.keys(normalized);
  if (ids.length === 0) {
    throw new GatewayError(
      400,
      "invalid_request_error",
      "At least one question is required.",
      "no_questions",
    );
  }
  if (ids.length > MAX_QUESTIONS) {
    throw new GatewayError(
      400,
      "invalid_request_error",
      `A judgement accepts at most ${MAX_QUESTIONS} questions.`,
      "too_many_questions",
    );
  }
  if (stateChars(state) > MAX_STATE_CHARS) {
    throw new GatewayError(
      400,
      "invalid_request_error",
      "`state` exceeds the judgement context budget.",
      "state_too_large",
    );
  }
  if (model !== undefined && typeof model !== "string") {
    throw new GatewayError(
      400,
      "invalid_request_error",
      "`model` must be a string when supplied.",
      "invalid_model",
    );
  }

  if (images !== undefined && (!Array.isArray(images) || images.length > 4 || images.some(image => typeof image !== 'string'))) {
    throw new GatewayError(400, 'invalid_request_error', 'Use at most four HTTPS or data URL images.', 'invalid_images');
  }
  if (allow_fallback !== undefined && typeof allow_fallback !== 'boolean') {
    throw new GatewayError(400, 'invalid_request_error', 'allow_fallback must be boolean.', 'invalid_fallback');
  }
  return {
    ...(images !== undefined ? { images: images as string[] } : {}),
    ...(allow_fallback !== undefined ? { allow_fallback: allow_fallback as boolean } : {}),
    state: state as Record<string, string> | string,
    questions: normalized as DecisionRequest["questions"],
    ...(typeof model === "string" ? { model } : {}),
  };
}

function stateChars(state: unknown): number {
  if (typeof state === "string") return state.length;
  if (!state || typeof state !== "object") return 0;
  return Object.values(state as Record<string, unknown>).reduce<number>(
    (total, value) => total + (typeof value === "string" ? value.length : 0),
    0,
  );
}

/** Pre-call ceiling. Deliberately generous; settlement uses real usage. */
function estimateMicrousd(request: JudgementRequest, backend: ResolvedDecisionBackend): number {
  const price = backend.price;
  if (price.unit === 'request') return judgementCost(price, 1);
  if (price.unit === 'gpu_second') return judgementCost(price, price.maxSeconds);
  const chars = stateChars(request.state) + JSON.stringify(request.questions).length;
  // Preserve the legacy text reservation estimate; images add explicit token headroom.
  const tokens = Math.ceil(chars / 4) * 2 + (request.images?.length ?? 0) * 8192;
  return Math.max(50, judgementCost(price, tokens));
}
function compatible(request: JudgementRequest, backend: ResolvedDecisionBackend): void {
  if (backend.backend === 'jev' && request.images?.length) throw new GatewayError(400, 'invalid_request_error', 'Jev does not support images.', 'images_unsupported');
  if (backend.backend === 'pplx' && Object.values(request.questions).some(q => q.type === 'score' && q.criteria.length > 10)) {
    throw new GatewayError(400, 'invalid_request_error', 'pplx score questions support at most ten levels.', 'invalid_criteria');
  }
}

function normalizedUsage(value: unknown): Usage | null {
  if (!value || typeof value !== "object") return null;
  const usage = value as Usage;
  const input = usage.input_tokens;
  const output = usage.output_tokens;
  if (
    typeof input !== "number" ||
    !Number.isSafeInteger(input) ||
    input < 0 ||
    typeof output !== "number" ||
    !Number.isSafeInteger(output) ||
    output < 0
  )
    return null;
  return { input_tokens: input, output_tokens: output };
}

/** Upstream error text can echo the caller's own document. Never forward it. */
function upstreamFailure(status: number): GatewayError {
  if (status === 429) {
    return new GatewayError(
      429,
      "rate_limit_error",
      "Judgements are rate limited upstream.",
      "judgement_rate_limited",
    );
  }
  if (status === 529) {
    return new GatewayError(
      503,
      "api_error",
      "Judgements are temporarily overloaded.",
      "judgement_overloaded",
    );
  }
  if (status === 401 || status === 403) {
    return new GatewayError(
      503,
      "api_error",
      "Judgements are not configured correctly.",
      "judgement_invalid_configuration",
    );
  }
  if (status === 422) {
    return new GatewayError(
      400,
      "invalid_request_error",
      "The judgement request was rejected as malformed.",
      "judgement_malformed",
    );
  }
  return new GatewayError(
    502,
    "api_error",
    "The judgement provider could not answer.",
    "judgement_upstream_error",
  );
}

export class JudgementGateway {
  constructor(private readonly config: GatewayConfig) {}

  /**
   * Reserve against the account, call TypeSafe, settle on real token usage.
   *
   * Settlement always runs: on an upstream failure the reservation is
   * released rather than left holding credit, and a response that arrives
   * without usage is reconciled at the reserved ceiling rather than billed at
   * zero. Both are the same discipline `PortkeyProxy` applies.
   */
  async evaluate(
    principal: VerifiedPrincipal,
    body: unknown,
    idempotencyKey: string,
    requestHash: string,
  ): Promise<JudgementResult> {
    const request = validated(body);
    let backend = resolveDecisionBackend(this.config, request.model);
    compatible(request, backend);
    const loaders = await Promise.all((request.images ?? []).map(prepareRepresentationImage));
    const fallbackName = request.allow_fallback ? this.config.decisions?.fallback?.[backend.backend] : undefined;
    let fallbackBackend: ResolvedDecisionBackend | undefined;
    if (fallbackName && fallbackName !== backend.backend) {
      try {
        const candidate = resolveDecisionBackend(this.config, `judgement-${fallbackName}`);
        compatible(request, candidate); fallbackBackend = candidate;
      } catch (error) {
        if (!(error instanceof GatewayError)) throw error;
      }
    }
    let fallback: JudgementFallback | undefined;
    let requestId: string = crypto.randomUUID();
    const maxCostMicrousd = estimateMicrousd(request, backend) + (fallbackBackend ? estimateMicrousd(request, fallbackBackend) : 0);
    if (
      maxCostMicrousd >
      Math.min(
        principal.maxCostMicrousd,
        this.config.maxAllowedCostMicrousd ?? Number.MAX_SAFE_INTEGER,
      )
    ) {
      throw new GatewayError(
        402,
        "insufficient_quota",
        "The judgement exceeds the request budget.",
        "budget_exceeded",
      );
    }

    const reservation = await this.config.store.reserve({
      requestId,
      idempotencyKey,
      orgContext: principal.orgContext, agentContext: principal.agentContext, sessionVersion: principal.sessionVersion,
      accountId: principal.accountId,
      product: principal.product,
      feature: "judgement",
      alias: request.model ?? JUDGEMENT_ALIAS,
      maxCostMicrousd,
      pricingVersion: this.config.pricingVersion ?? "v1",
      requestHash,
    });
    if (reservation.status === "settled" && reservation.response) {
      const { model, answers, usage, fallback } = reservation.response;
      return { model, answers, usage, ...(fallback ? { fallback } : {}) } as JudgementResult;
    }
    if (reservation.status !== "reserved") {
      throw new GatewayError(
        409,
        "conflict_error",
        "This judgement request has already been submitted.",
        "idempotency_conflict",
      );
    }
    requestId = reservation.requestId;

    try {
      if (loaders.length) request.images = await Promise.all(loaders.map(load => load()));
    } catch (error) {
      await this.config.store.release({ requestId, reason: 'image_preparation_failed' });
      throw error;
    }

    try {
      await this.config.store.markDispatched({ requestId });
    } catch (error) {
      await this.config.store.release({
        requestId,
        reason: "dispatch_not_started",
      });
      throw error;
    }

    let response: Response;
    try {
      response = await this.#fetch(backend, request);
      // Only explicit overload rejections are eligible. Never repeat ambiguous delivery or accepted work.
      if ([429, 529].includes(response.status) && fallbackBackend) {
        fallback = { from: `judgement-${backend.backend}/${backend.model}`, to: `judgement-${fallbackBackend.backend}/${fallbackBackend.model}`, reason: `upstream_${response.status}` };
        backend = fallbackBackend;
        response = await this.#fetch(backend, request);
      }
    } catch {
      await this.config.store.reconcile({
        requestId,
        conservativeCostMicrousd: maxCostMicrousd,
        reason: "judgement_delivery_unknown",
      });
      throw new GatewayError(
        502,
        "api_error",
        "The judgement provider could not be reached.",
        "judgement_unreachable",
      );
    }

    if (!response.ok) {
      await this.config.store.release({
        requestId,
        reason: `upstream_${response.status}`,
      });
      throw upstreamFailure(response.status);
    }

    await this.config.store.markAccepted({ requestId });
    const payload: unknown = await boundedJson(response).catch(() => null);
    let answers: Record<string, unknown>;
    let model: string;
    try {
      if (!record(payload) || typeof payload.model !== 'string' || !payload.model.trim() || ['judgement', 'jev-latest', 'autojev'].includes(payload.model)) throw new Error('Missing concrete model identity');
      if (backend.backend === 'luna' && !/^gpt-6-luna(?:-|$)/.test(payload.model)) throw new Error('Unexpected Luna model');
      answers = backend.backend === 'luna' ? fromLunaAnswers(request.questions, payload.answers) : validateDecisionAnswers(request.questions, payload.answers);
      model = `judgement-${backend.backend}/${payload.model}`;
      if (fallback) fallback.to = model;
    } catch {
      await this.config.store.reconcile({ requestId, conservativeCostMicrousd: maxCostMicrousd, reason: 'invalid_upstream_response' });
      throw new GatewayError(502, 'api_error', 'The judgement provider returned invalid answers or model identity.', 'judgement_invalid_response');
    }
    const usage = normalizedUsage((payload as Record<string, unknown>).usage);
    const price = backend.price;
    const rawUsage = record(payload) && record(payload.usage) ? payload.usage : null;
    const seconds = rawUsage?.gpu_seconds;
    if (usage && backend.backend === "pplx" && typeof seconds === "number" && Number.isFinite(seconds) && seconds >= 0) usage.gpu_seconds = seconds;
    let cost: number | null = null;
    try {
      cost = price.unit === 'request' ? judgementCost(price, 1)
        : price.unit === 'gpu_second' ? (typeof seconds === 'number' && Number.isFinite(seconds) && seconds >= 0 ? judgementCost(price, seconds) : null)
        : usage ? judgementCost(price, usage.input_tokens!) : null;
    } catch { /* Invalid or overflowing reported usage is reconciled at the reservation ceiling. */ }
    if (cost === null) {
      // Answers without usage: bill conservatively at the ceiling rather than
      // give the call away, and mark it so it can be trued up out of band.
      await this.config.store.reconcile({
        requestId,
        conservativeCostMicrousd: maxCostMicrousd,
        reason: "judgement_usage_unavailable",
      });
    } else {
      const charged = Math.min(cost, maxCostMicrousd);
      await this.config.store.settleWithResponse({
        accountId: principal.accountId,
        orgContext: principal.orgContext,
        response: {
          id: requestId,
          object: "judgement",
          model,
          answers,
          ...(fallback ? { fallback } : {}),
          usage,
        },
        requestId,
        actualCostMicrousd: charged,
        providerAbsorbedMicrousd: Math.max(0, cost - charged),
        usage: usage ?? undefined,
      });
    }

    await this.#emitSettled(principal, {
      product: principal.product,
      alias: request.model ?? JUDGEMENT_ALIAS,
      backend: backend.backend,
      model,
      questions: Object.keys(request.questions).length,
      input_tokens: usage?.input_tokens ?? null,
      usage_complete: usage !== null,
      billed_usd:
        (cost === null ? maxCostMicrousd : Math.min(cost, maxCostMicrousd)) /
        1_000_000,
    });

    return { model, answers, usage, ...(fallback ? { fallback } : {}) };
  }

  models(): string[] {
    return ['judgement', 'judgement-vision', 'judgement-jev', 'judgement-luna', 'judgement-pplx'].filter(alias => {
      try { resolveDecisionBackend(this.config, alias); return true; } catch { return false; }
    });
  }

  #fetch(backend: ResolvedDecisionBackend, request: JudgementRequest): Promise<Response> {
    const origin = (backend.apiOrigin ?? (backend.backend === 'luna' ? 'https://api.openai.com' : DEFAULT_TYPESAFE_ORIGIN)).replace(/\/$/, '');
    return (this.config.fetch ?? fetch)(`${origin}${backend.backend === 'luna' ? '/v1/decisions' : '/v1/systemone'}`, {
      method: 'POST', redirect: 'error', signal: AbortSignal.timeout(backend.backend === 'pplx' ? 180_000 : 30_000),
      headers: { 'content-type': 'application/json', authorization: `Bearer ${backend.apiKey}` },
      body: JSON.stringify(backend.backend === 'luna' ? lunaBody(request) : {
        model: backend.model, state: request.state, questions: request.questions,
        ...(request.images?.length ? { images: request.images } : {}),
      }),
    });
  }

  /**
   * Analytics are keyed by an HMAC of the account id, never the id itself —
   * the same derivation `PortkeyProxy` uses, so judgement spend joins the
   * existing per-account series without putting a real identifier in PostHog.
   *
   * Keep the HMAC derivation aligned with PortkeyProxy so account spend joins
   * the same pseudonymous series without exposing the account identifier.
   */
  async #emitSettled(
    principal: VerifiedPrincipal,
    properties: Record<string, unknown>,
  ): Promise<void> {
    const telemetry = this.config.telemetry;
    if (!telemetry) return;
    try {
      const key = await crypto.subtle.importKey(
        "raw",
        new Uint8Array(this.config.pseudonymSecret).buffer as ArrayBuffer,
        { name: "HMAC", hash: "SHA-256" },
        false,
        ["sign"],
      );
      const digest = new Uint8Array(
        await crypto.subtle.sign(
          "HMAC",
          key,
          new TextEncoder().encode(principal.accountId),
        ),
      );
      await telemetry.capture(
        "judgement.settled",
        Buffer.from(digest).toString("base64url"),
        properties,
      );
    } catch {
      // Telemetry must never fail a settled judgement the writer already paid
      // for and is waiting on.
    }
  }
}
export const JUDGEMENT_MODELS = ['judgement', 'judgement-vision', 'judgement-jev', 'judgement-luna', 'judgement-pplx'] as const;
export type JudgementBackend = 'jev' | 'luna' | 'pplx';
export type JudgementQuestion =
  | { type: 'noul'; instructions: string; criteria?: { true: string; false: string } }
  | { type: 'choice'; instructions: string; criteria: Record<string, string | null> }
  | { type: 'score'; instructions: string; criteria: string[] };
export interface JudgementRequest {
  state: Record<string, string> | string;
  questions: Record<string, JudgementQuestion>;
  model?: string;
  images?: string[];
  allow_fallback?: boolean;
}
export type JudgementAnswer =
  | { type: 'noul'; noul: number }
  | { type: 'choice'; choice: string; probabilities: Record<string, number>; confidence: number }
  | { type: 'score'; score: number; probabilities: Record<string, number>; legend: Record<string, string>; confidence: number };
export interface JudgementFallback { from: string; to: string; reason: string }
# Multi-backend decision gateway

`POST /v1/judgement` requires DPoP and `judgement:evaluate`. Products retain System One
`{ state, questions, model?, images?, allow_fallback? }` → `{ model, answers, usage, fallback? }`.
State is a string or a map of strings. Questions are a named map of `noul`, `choice`, or
`score` with instructions and criteria. Legacy choice-label arrays normalize to a map.
No chat prompt or textual answer parsing is introduced.

## Aliases and configuration

`judgement-jev` → TypeSafe Jev (text only); images return 400 `images_unsupported`.
`judgement-luna` → OpenAI `gpt-6-luna` Decisions; `judgement-pplx` → self-hosted
`pplx-decider-v1.1-27b` System One. `judgement` follows `JUDGEMENT_TEXT_BACKEND`
(`jev` by default); `judgement-vision` follows `JUDGEMENT_VISION_BACKEND` (`luna` or `pplx`,
no default). Missing credential or price returns 503 `model_unavailable`, and the alias
is omitted from `GET /v1/models`. Jev retains its published default of **0.042 microUSD/input token** for existing
key-only deployments. Luna and pplx have **no default prices**.

Gateway-only env:

- Jev: `TYPESAFE_API_KEY`, optional `TYPESAFE_MODEL` (default `jev-latest`),
  `TYPESAFE_API_ORIGIN` (default https://api.typesafe.ai),
  optional `JUDGEMENT_JEV_PRICE_PER_INPUT_TOKEN_MICROUSD` (default 0.042; a supplied
  override must be finite and positive). `TYPESAFE_API_KEY` alone enables
  `judgement` and `judgement-jev`, with the legacy text reservation estimate and rate.
- Luna: `OPENAI_DECISIONS_API_KEY`, `JUDGEMENT_LUNA_PRICE_PER_INPUT_TOKEN_MICROUSD`.
  The [Decisions guide](https://developers.openai.com/api/docs/guides/decisions) quotes
  $0.10/M input tokens (0.1 microUSD/token), output free. Set the intended retail rate
  explicitly, accounting for regional/long-context premiums and provider margin.
- pplx: `PPLX_DECIDER_ORIGIN`, `PPLX_DECIDER_API_KEY`, optional `PPLX_DECIDER_MODEL`,
  `PPLX_DECIDER_PRICE_PER_REQUEST_MICROUSD` OR
  `PPLX_DECIDER_PRICE_PER_GPU_SECOND_MICROUSD` + `PPLX_DECIDER_MAX_SECONDS`.
  For Runpod direct HTTP, use a separate least-privilege Runpod inference key as both
  `PPLX_DECIDER_API_KEY` and worker `AUTOJEV_API_KEY` (see deployment guide).
  The configured seconds ceiling determines the reservation; trusted upstream
  `usage.gpu_seconds` determines settlement. Missing seconds reconciles at the ceiling.
- Optional `JUDGEMENT_JEV_FALLBACK`, `JUDGEMENT_LUNA_FALLBACK`, `JUDGEMENT_PPLX_FALLBACK`
  contain one backend (`jev`, `luna`, `pplx`). These have effect only when the caller sets
  `allow_fallback: true`, only after HTTP 429/529, and only for a configured compatible
  backend. No fallback on unconfigured models, transport uncertainty, malformed accepted
  responses, refusals, or generic errors. At most two attempts; no chain.

The response model is always `judgement-BACKEND/UPSTREAM_MODEL`, e.g.
`judgement-luna/gpt-6-luna` or `judgement-pplx/pplx-decider-v1.1-27b@REVISION`.
Products must keep separate thresholds/calibration per concrete identity.
An executed fallback adds `{ from, to, reason }` and is retained on replay.
Previously accepted raw Jev model selectors must migrate to `judgement-jev`.

## Verified Luna wire (2026-10-11)

[API reference](https://developers.openai.com/api/reference/resources/decisions/methods/create):
POST `https://api.openai.com/v1/decisions` with `model: gpt-6-luna`,
`input: [{role: user, content: [{type: input_text, text}, {type: input_image, image_url}]}]`,
and a `questions` array. Every question has a unique `name` and string `instructions`.
`noul` maps to `predicate`; the reply's `probability` becomes `noul` unchanged.
Luna has no predicate criteria field: authored poles are appended as a JSON criteria
section in instructions (including a null marker when absent, ensuring invertibility).
Choice maps become `choices: [{value, description?}]`; null descriptions are omitted.
Score arrays become ordered `levels: [{label}]`. Score replies include `score`,
`confidence`, and `{value: numericIndex, label, probability}` entries. Gateway answers
restore indexed probability maps and `legend`. Choice replies restore probability maps
from `{value, probability}` entries. Confidence passes through unchanged.

One authorized live text-plus-public-image call returned HTTP 200, `gpt-6-luna`, all three
answer types, 406 input tokens (image included), and 0 output tokens. No further live calls
were made. This verifies the wire, not funded production gateway accounting.

All adapters validate exact question/option coverage, finite probabilities in [0,1],
sum within `N * 0.0000005 + EPSILON * N`, choice argmax, score legend and weighted mean
within the same squared-level rounding tolerance as Interleave's judgement/wire.ts.
Probabilities are never repaired or renormalized. Refusals/incomplete answers are rejected
and reconciled after acceptance; they are never converted to false or zero confidence.

## Images and accounting

At most four base64 PNG/JPEG/WebP data URLs or public HTTPS URLs, 5 MB decoded/downloaded
per image. HTTPS images are resolved and pinned to public addresses, fetched without
redirects and converted to data URLs before dispatch. No file paths, HTTP, credentials,
private networks or URL fragments. Total HTTP body cap is 28 MB, checked while streaming;
upstream JSON is bounded to 1 MB. Jev rejects nonempty images before reservation.
Question cap 64; state and question JSON caps 96k characters each. pplx scores have at
most ten levels; its upstream enforces 8192 tokens/branch without truncation and verifies
image format/pixel caps. Luna's larger image allowance is intentionally capped here.

Idempotency key is optional (1–255 characters); omission starts a new evaluation.
Reserve → dispatch → accept → settlement and the encrypted response ledger remain
unchanged. Settled replay returns the original answers, model and fallback without
another upstream call or charge. In-flight duplicates return 409. Prices are retail
microUSD/unit, rounded up to integer money. Token settlement uses reported total input
(including image tokens), output free. Request pricing can settle without token usage;
`usage` remains null if unavailable. Unknown delivery or unavailable required usage
reconciles at the reserved ceiling. Costs beyond the ceiling are provider-absorbed.
When eligible fallback is enabled, reservation covers both potential calls.

## Self-hosting and checks

See [Runpod deployment](../../../../infra/runpod/pplx-decider/deploy.md) for the CUDA/PyTorch
packaging limitation, exact approved deployment commands, secrets, readiness, smoke and
cost assumptions. No Runpod resource creation or spending is authorized by this bundle.

Focused checks: `rtk proxy bun test apps/gateway/src/judgement.test.ts`.
Repo check: `rtk proxy bun run check`. Container/GPU tests and production account-to-ledger
verification remain separate from the fake-upstream checks.

