import { describe, expect, mock, test } from "bun:test";
import { JudgementGateway } from "./judgement";
import type { ProviderStore, VerifiedPrincipal } from "./types";

const principal: VerifiedPrincipal = {
  accountId: "did:plc:alice", product: "keating",
  scopes: new Set(["judgement:evaluate"]), jkt: "test-jkt",
  maxCostMicrousd: 100_000, tokenType: "user", environment: "browser",
};

function fixture(usage: unknown = { input_tokens: 100, output_tokens: 0 }) {
  const requests: Request[] = [];
  const events: Array<Record<string, unknown> | undefined> = [];
  const store = { getAccount: async () => ({ account: null }),
    reserve: mock(async ({ requestId }: { requestId: string }) => ({ requestId, status: "reserved" as const })),
    markDispatched: mock(async () => {}), markAccepted: mock(async () => {}),
    settleWithResponse: mock(async () => {}), release: mock(async () => {}),
    reconcile: mock(async () => {}),
  };
  const gateway = new JudgementGateway({
    store: store as unknown as ProviderStore, portkeyApiKey: "unused",
    gatewayIssuer: "https://gateway.test", gatewayAudience: "notorganic",
    gatewaySigningPrivateJwk: {}, gatewaySigningPublicJwk: {},
    pseudonymSecret: new Uint8Array(32),
    decisions: { jev: { apiKey: "test-provider-key", price: { unit: "input_token", microusd: 0.042 } } },
    typesafe: { apiKey: "test-provider-key", model: "jev-test-version" },
    telemetry: { enabled: true, capture: async (_event, _id, properties) => { events.push(properties); } },
    fetch: async (input, init) => {
      requests.push(new Request(input, init));
      return Response.json({ model: "jev-test-version", answers: { answer: { type: "noul", noul: 0.8 } }, usage });
    },
  });
  return {
    requests, store, events,
    evaluate: (question: unknown) => gateway.evaluate(principal, {
      model: "judgement", state: "The learner explains their reasoning.", questions: { answer: question },
    }, "test-idempotency", "test-request-hash"),
  };
}

describe("judgement Noul criteria", () => {
  test("forwards both authored poles unchanged through the metered provider boundary", async () => {
    const { evaluate, requests, store } = fixture();
    const question = { type: "noul", instructions: "Does the learner understand?", criteria: {
      true: "Yes: applies the rule and explains why it works.",
      false: "No: repeats a rule without connecting it to the example.",
    } };
    const result = await evaluate(question);
    expect(await requests[0]!.json()).toEqual({
      model: "jev-test-version", state: "The learner explains their reasoning.", questions: { answer: question },
    });
    expect(result.model).toBe("judgement-jev/jev-test-version");
    expect(requests[0]!.redirect).toBe("error");
    expect(store.reserve).toHaveBeenCalledTimes(1);
    expect(store.settleWithResponse).toHaveBeenCalledTimes(1);
    expect(store.reconcile).not.toHaveBeenCalled();
  });

  test("keeps criteria optional", async () => {
    const { evaluate, requests } = fixture();
    const question = { type: "noul", instructions: "Is the answer correct?" };
    await evaluate(question);
    expect((await requests[0]!.json()).questions.answer).toEqual(question);
  });

  for (const usage of [null, {}, { input_tokens: 100 }, { input_tokens: -1, output_tokens: 0 }]) {
    test(`keeps unavailable usage unknown in responses and telemetry: ${JSON.stringify(usage)}`, async () => {
      const { evaluate, store, events } = fixture(usage);
      const result = await evaluate({ type: "noul", instructions: "Correct?" });
      expect(result.usage).toBeNull();
      expect(store.reconcile).toHaveBeenCalledTimes(1);
      expect(store.settleWithResponse).not.toHaveBeenCalled();
      expect(events).toHaveLength(1);
      expect(events[0]).toMatchObject({ input_tokens: null, usage_complete: false });
      expect(events[0]!.billed_usd).toBeGreaterThan(0);
    });
  }

  test("preserves explicit zero usage as known", async () => {
    const { evaluate, store, events } = fixture({ input_tokens: 0, output_tokens: 0 });
    const result = await evaluate({ type: "noul", instructions: "Correct?" });
    expect(result.usage).toEqual({ input_tokens: 0, output_tokens: 0 });
    expect(store.reconcile).not.toHaveBeenCalled();
    expect(events[0]).toMatchObject({ input_tokens: 0, usage_complete: true, billed_usd: 0 });
  });

  for (const criteria of [null, [], ["yes", "no"], "yes", { true: "yes" }, { true: "yes", false: null }, { true: 1, false: "no" }, { true: "yes", false: "no", extra: "maybe" }]) {
    test(`rejects malformed poles before reservation or upstream: ${JSON.stringify(criteria)}`, async () => {
      const { evaluate, requests, store } = fixture();
      await expect(evaluate({ type: "noul", instructions: "Is the answer correct?", criteria }))
        .rejects.toMatchObject({ status: 400, code: "invalid_criteria" });
      expect(store.reserve).not.toHaveBeenCalled();
      expect(requests).toHaveLength(0);
    });
  }

  test("includes preserved poles in the context limit before spending", async () => {
    const { evaluate, requests, store } = fixture();
    await expect(evaluate({ type: "noul", instructions: "Correct?", criteria: { true: "x".repeat(96_000), false: "No" } }))
      .rejects.toMatchObject({ status: 400, code: "questions_too_large" });
    expect(store.reserve).not.toHaveBeenCalled();
    expect(requests).toHaveLength(0);
  });
});

