import { TabPfnClient } from "../../../packages/tabpfn-client/src/index";
import { GatewayError } from "./errors";
import type { GatewayConfig, VerifiedPrincipal } from "./types";

export const TABULAR_MODEL = "v3.5_default" as const;
/** Sized for trusted product servers; browser and mobile tables are bounded far lower in validation. */
export const TABULAR_MAX_BODY_BYTES = 4_000_000;
const TIMEOUT_MS = 120_000;
export type TabularTask = "regression" | "classification";
export interface TabularLimits { maxTrainRows: number; maxTestRows: number; maxFeatures: number }
/** Browser and mobile clients keep the original bounds; trusted product servers batch larger tables. */
export const TABULAR_CLIENT_LIMITS = { maxTrainRows: 500, maxTestRows: 64, maxFeatures: 32 } as const satisfies TabularLimits;
export const TABULAR_SERVER_LIMITS = { maxTrainRows: 4096, maxTestRows: 1024, maxFeatures: 64 } as const satisfies TabularLimits;
/** One price unit covers this many table cells; every client-sized table is exactly one unit. */
export const TABULAR_CELLS_PER_PRICE_UNIT = 20_000;
/** Add future provider adapters here only once their transport and billing are implemented. */
export const TABULAR_MODELS = [{
  id: TABULAR_MODEL, name: "TabPFN 3.5", provider: "priorlabs", tasks: ["regression", "classification"],
  limits: TABULAR_CLIENT_LIMITS, serverLimits: TABULAR_SERVER_LIMITS,
}] as const;
export type TabularModel = (typeof TABULAR_MODELS)[number];
export interface TabularModelListing {
  id: TabularModel["id"];
  name: string;
  provider: TabularModel["provider"];
  /** The schema 1 task; existing clients check this field. */
  task: "regression";
  /** Every task schema 2 accepts. */
  tasks: readonly TabularTask[];
  available: boolean;
  /** Price of one unit; a request costs ceil(cells / cellsPerPriceUnit) units. */
  priceMicrousd: number | null;
  cellsPerPriceUnit: number;
  /** The bounds for the calling principal. */
  limits: TabularLimits;
}

/**
 * Schema 1 is the original Keating contract: regression over targets in [0, 1], clamped outputs.
 * Schema 2 adds binary classification (probability of label 1) and unbounded regression targets.
 */
export type TabularRequest = {
  schemaVersion: 1;
  task: "regression";
  model: typeof TABULAR_MODEL;
  featureNames: string[];
  trainFeatures: number[][];
  trainTargets: number[];
  testFeatures: number[][];
} | {
  schemaVersion: 2;
  task: TabularTask;
  model: typeof TABULAR_MODEL;
  featureNames: string[];
  trainFeatures: number[][];
  trainTargets: number[];
  testFeatures: number[][];
};
export interface TabularResult {
  model: typeof TABULAR_MODEL;
  /** Regression means, or for classification the probability of label 1. */
  predictions: number[];
}
type TabularInference = (request: TabularRequest, signal: AbortSignal) =>
  Promise<{ modelPath: string; predictions: unknown; classes?: unknown }>;

export function tabularLimitsFor(principal: Pick<VerifiedPrincipal, "environment">): TabularLimits {
  return principal.environment === "server" ? TABULAR_SERVER_LIMITS : TABULAR_CLIENT_LIMITS;
}

export function tabularPriceUnits(request: Pick<TabularRequest, "featureNames" | "trainFeatures" | "testFeatures">): number {
  const cells = (request.trainFeatures.length + request.testFeatures.length) * request.featureNames.length;
  return Math.max(1, Math.ceil(cells / TABULAR_CELLS_PER_PRICE_UNIT));
}

/** A retail price is an operator decision, never inferred from provider tokens. */
export function tabularConfigFromEnv(env: Record<string, string | undefined>): GatewayConfig["tabular"] {
  const apiKey = env.TABPFN_API_KEY?.trim();
  const rawPrice = env.TABPFN_PRICE_MICROUSD_PER_REQUEST?.trim();
  if (!apiKey || !rawPrice) return undefined;
  const priceMicrousd = Number(rawPrice);
  if (!/^\d+$/.test(rawPrice) || !Number.isSafeInteger(priceMicrousd) || priceMicrousd <= 0) {
    throw new Error("TABPFN_PRICE_MICROUSD_PER_REQUEST must be a positive integer.");
  }
  return { apiKey, priceMicrousd };
}

function invalid(message = "Use the bounded numeric tabular request schema."): never {
  throw new GatewayError(400, "invalid_request_error", message, "tabular_request_invalid");
}

export function validateTabularRequest(body: unknown, limits: TabularLimits = TABULAR_CLIENT_LIMITS): TabularRequest {
  if (!body || typeof body !== "object" || Array.isArray(body)) invalid();
  const row = body as Record<string, unknown>;
  const model = TABULAR_MODELS.find(model => model.id === row.model);
  if (Object.keys(row).sort().join(",") !== "featureNames,model,schemaVersion,task,testFeatures,trainFeatures,trainTargets"
    || !model) invalid();
  const v1 = row.schemaVersion === 1 && row.task === "regression";
  const v2 = row.schemaVersion === 2 && (model.tasks as readonly unknown[]).includes(row.task);
  if (!v1 && !v2) invalid();
  if (!Array.isArray(row.featureNames) || row.featureNames.length < 1 || row.featureNames.length > limits.maxFeatures
    || row.featureNames.some(name => typeof name !== "string" || !/^[A-Za-z][A-Za-z0-9_]{0,63}$/.test(name))
    || new Set(row.featureNames).size !== row.featureNames.length) invalid();
  const width = row.featureNames.length;
  const matrix = (value: unknown, min: number, max: number): value is number[][] => Array.isArray(value)
    && value.length >= min && value.length <= max
    && value.every(values => Array.isArray(values) && values.length === width
      && values.every(cell => typeof cell === "number" && Number.isFinite(cell)));
  if (!matrix(row.trainFeatures, 2, limits.maxTrainRows) || !matrix(row.testFeatures, 1, limits.maxTestRows)
    || !Array.isArray(row.trainTargets) || row.trainTargets.length !== row.trainFeatures.length
    || row.trainTargets.some(target => typeof target !== "number" || !Number.isFinite(target))) invalid();
  const targets = row.trainTargets as number[];
  // Schema 1 targets are probabilities. Classification needs both labels present as context.
  if (v1 && targets.some(target => target < 0 || target > 1)) invalid();
  if (row.task === "classification" && (targets.some(target => target !== 0 && target !== 1) || new Set(targets).size !== 2)) {
    invalid("Classification targets must contain both labels 0 and 1.");
  }
  return row as unknown as TabularRequest;
}

/** Fails closed on any shape the request did not ask for; tables never pass through here. */
function checkedPredictions(request: TabularRequest, output: { modelPath: string; predictions: unknown; classes?: unknown }): number[] {
  const rows = request.testFeatures.length;
  if (output.modelPath !== TABULAR_MODEL || !Array.isArray(output.predictions) || output.predictions.length !== rows) {
    throw new Error("Invalid prediction response");
  }
  if (request.task === "classification") {
    const classes = output.classes;
    if (!Array.isArray(classes) || classes.length !== 2 || !classes.includes(0) || !classes.includes(1)) throw new Error("Invalid classes");
    const positive = classes.indexOf(1);
    return output.predictions.map(pair => {
      if (!Array.isArray(pair) || pair.length !== 2 || pair.some(p => typeof p !== "number" || !Number.isFinite(p) || p < 0 || p > 1)) {
        throw new Error("Invalid probabilities");
      }
      return pair[positive] as number;
    });
  }
  if (output.predictions.some(value => typeof value !== "number" || !Number.isFinite(value))) throw new Error("Invalid prediction response");
  const values = output.predictions as number[];
  // Schema 1 targets are probabilities, so its regression estimates stay in [0, 1]. Schema 2 regression is unbounded.
  return request.schemaVersion === 1 ? values.map(value => Math.max(0, Math.min(1, value))) : values;
}

/** One stateless table prediction is one account operation, priced per unit of table cells. */
export class TabularGateway {
  private readonly active = new Set<string>();
  private readonly windows = new Map<string, { startedAt: number; count: number }>();

  constructor(private readonly config: GatewayConfig, private readonly infer?: TabularInference) {}

  models(principal?: Pick<VerifiedPrincipal, "environment">): { models: TabularModelListing[] } {
    return { models: TABULAR_MODELS.map(model => {
      const config = model.provider === "priorlabs" ? this.config.tabular : undefined;
      const priced = !!config && Number.isSafeInteger(config.priceMicrousd) && config.priceMicrousd > 0;
      return { id: model.id, name: model.name, provider: model.provider, task: "regression", tasks: model.tasks,
        available: priced && !!config?.apiKey.trim(), priceMicrousd: priced ? config.priceMicrousd : null,
        cellsPerPriceUnit: TABULAR_CELLS_PER_PRICE_UNIT,
        limits: principal ? tabularLimitsFor(principal) : model.limits };
    }) };
  }

  async predict(principal: VerifiedPrincipal, body: unknown, options: {
    idempotencyKey: string;
    requestHash: string;
    maxCostMicrousd?: number;
    signal?: AbortSignal;
  }): Promise<TabularResult> {
    const request = validateTabularRequest(body, tabularLimitsFor(principal));
    const configured = this.config.tabular;
    if (!configured?.apiKey.trim() || !Number.isSafeInteger(configured.priceMicrousd) || configured.priceMicrousd <= 0) {
      throw new GatewayError(503, "api_error", "Tabular predictions are not configured.", "tabular_unavailable");
    }
    const units = tabularPriceUnits(request);
    const cost = configured.priceMicrousd * units;
    if (cost > Math.min(principal.maxCostMicrousd, options.maxCostMicrousd ?? Number.MAX_SAFE_INTEGER,
      this.config.maxAllowedCostMicrousd ?? Number.MAX_SAFE_INTEGER)) {
      throw new GatewayError(402, "insufficient_quota", "The tabular prediction exceeds the request budget.", "budget_exceeded");
    }
    if (options.signal?.aborted) throw new GatewayError(408, "api_error", "The tabular prediction was cancelled.", "tabular_cancelled");
    // Product servers batch many recruits per call and poll per campaign, so they get a wider window.
    this.acquire(principal.accountId, principal.environment === "server" ? 30 : 6);
    try {
      let requestId: string = crypto.randomUUID();
      const reservation = await this.config.store.reserve({ requestId, accountId: principal.accountId, product: principal.product, orgContext: principal.orgContext, agentContext: principal.agentContext, sessionVersion: principal.sessionVersion,
        feature: "tabular-prediction", alias: "tabular", maxCostMicrousd: cost,
        pricingVersion: units === 1 ? `tabular-fixed-v1:${cost}` : `tabular-cells-v2:${configured.priceMicrousd}x${units}`, idempotencyKey: options.idempotencyKey, requestHash: options.requestHash });
      if (reservation.status === "settled" && reservation.response) {
        return { model: TABULAR_MODEL, predictions: reservation.response.predictions as number[] };
      }
      if (reservation.status !== "reserved") {
        throw new GatewayError(409, "conflict_error", "This tabular request has already been submitted.", "idempotency_conflict");
      }
      requestId = reservation.requestId;
      try { await this.config.store.markDispatched({ requestId }); }
      catch (error) { await this.config.store.release({ requestId, reason: "dispatch_not_started" }); throw error; }

      // The SDK's stateless operation cleans up both uploaded tables, including on failure.
      // Only the numeric prediction response is stored for idempotency; tables are never stored here.
      let result: TabularResult;
      try {
        const signal = options.signal ? AbortSignal.any([options.signal, AbortSignal.timeout(TIMEOUT_MS)]) : AbortSignal.timeout(TIMEOUT_MS);
        const output = this.infer ? await this.infer(request, signal) : await new TabPfnClient({
          apiKey: configured.apiKey, fetch: this.config.fetch, timeoutMs: TIMEOUT_MS,
        }).fitPredict({ task: request.task, columns: request.featureNames,
          rows: request.trainFeatures, targets: request.trainTargets, testRows: request.testFeatures, signal });
        result = { model: TABULAR_MODEL, predictions: checkedPredictions(request, output) };
      } catch {
        await this.config.store.reconcile({ requestId, conservativeCostMicrousd: cost, reason: "tabular_delivery_unknown" });
        throw new GatewayError(502, "api_error", "The tabular prediction could not be completed.", "tabular_unavailable");
      }
      try {
        await this.config.store.markAccepted({ requestId });
        await this.config.store.settleWithResponse({ requestId, accountId: principal.accountId, orgContext: principal.orgContext, actualCostMicrousd: cost,
          response: { id: requestId, object: "tabular.prediction", ...result } });
      } catch {
        await this.config.store.reconcile({ requestId, conservativeCostMicrousd: cost, reason: "tabular_settlement_unknown" });
        throw new GatewayError(502, "api_error", "The tabular prediction could not be settled.", "tabular_unavailable");
      }
      return result;
    } finally { this.active.delete(principal.accountId); }
  }

  private acquire(accountId: string, perMinute: number, now = Date.now()): void {
    for (const [key, window] of this.windows) if (now - window.startedAt >= 60_000) this.windows.delete(key);
    const window = this.windows.get(accountId);
    // These per-process limits complement the durable wallet reservation/spend limits.
    if (this.active.has(accountId) || this.active.size >= 8 || (window?.count ?? 0) >= perMinute || (!window && this.windows.size >= 10_000)) {
      throw new GatewayError(429, "rate_limit_error", "Wait before requesting another tabular prediction.", "tabular_rate_limited");
    }
    this.windows.set(accountId, { startedAt: window?.startedAt ?? now, count: (window?.count ?? 0) + 1 });
    this.active.add(accountId);
  }
}
