const keys = await generateKeyPair("EdDSA", { extractable: true });
async function authorized(scope: string, overrides: Record<string, string> = {}, proofPath = "/v1/tabular/predict", method = "POST", path = "/v1/tabular/predict") {
  const device = await generateKeyPair("ES256"), jwk = await exportJWK(device.publicKey);
  const token = await new SignJWT({ typ: "notorganic/access+jwt", product: "keating", assertion_jti: "test-assertion",
    token_type: "user", session_version: 1, capabilities: [scope], cnf: { jkt: await calculateJwkThumbprint(jwk) }, max_cost_microusd: 100_000 })
    .setProtectedHeader({ alg: "EdDSA" }).setIssuer("https://gateway.test").setAudience("notorganic")
    .setSubject(principal.accountId).setIssuedAt().setExpirationTime("5m").setJti(crypto.randomUUID()).sign(keys.privateKey);
  const ath = Buffer.from(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(token))).toString("base64url");
  const dpop = await new SignJWT({ htm: method, htu: `https://gateway.test${proofPath}`, ath })
    .setProtectedHeader({ alg: "ES256", typ: "dpop+jwt", jwk }).setIssuedAt().setJti(crypto.randomUUID()).sign(device.privateKey);
  return new Request(`https://gateway.test${path}`, { method, ...(method === "GET" ? {} : { body: JSON.stringify(body) }),
    headers: { "content-type": "application/json", authorization: `DPoP ${token}`, dpop, "idempotency-key": "test-idem", ...overrides } });
}

test("HTTP route enforces DPoP, scope, idempotency, budget and configuration before inference", async () => {
  const { config, store } = fixture();
  config.gatewaySigningPrivateJwk = await exportJWK(keys.privateKey); config.gatewaySigningPublicJwk = await exportJWK(keys.publicKey);
  config.tabular = undefined;
  const app = createGateway(config);
  expect((await app.fetch(new Request("https://gateway.test/v1/tabular/predict", { method: "POST", body: JSON.stringify(body) }))).status).toBe(401);
  expect((await app.fetch(await authorized("wallet:read"))).status).toBe(403);
  expect((await app.fetch(await authorized("tabular:predict", {}, "/v1/judgement"))).status).toBe(401);
  expect((await app.fetch(await authorized("tabular:predict", { "idempotency-key": "" }))).status).toBe(400);
  expect((await app.fetch(await authorized("tabular:predict", { "x-notorganic-max-cost-microusd": "-1" }))).status).toBe(400);
  expect((await app.fetch(await authorized("tabular:predict"))).status).toBe(503);
  expect(store.reserve).not.toHaveBeenCalled();
});

