function normalizedUsage(value: unknown): Usage | null {
  if (!value || typeof value !== "object") return null;
  const usage = value as Usage;
  const input = usage.input_tokens;
  const output = usage.output_tokens;
  if (
    typeof input !== "number" ||
    !Number.isSafeInteger(input) ||
    input < 0 ||
    typeof output !== "number" ||
    !Number.isSafeInteger(output) ||
    output < 0
  )
    return null;
  return { input_tokens: input, output_tokens: output };
}

/** Upstream error text can echo the caller's own document. Never forward it. */
function upstreamFailure(status: number): GatewayError {
  if (status === 429) {
    return new GatewayError(
      429,
      "rate_limit_error",
      "Judgements are rate limited upstream.",
      "judgement_rate_limited",
    );
  }
  if (status === 529) {
    return new GatewayError(
      503,
      "api_error",
      "Judgements are temporarily overloaded.",
      "judgement_overloaded",
    );
  }
  if (status === 401 || status === 403) {
    return new GatewayError(
      503,
      "api_error",
      "Judgements are not configured correctly.",
      "judgement_invalid_configuration",
    );
  }
  if (status === 422) {
    return new GatewayError(
      400,
      "invalid_request_error",
      "The judgement request was rejected as malformed.",
      "judgement_malformed",
    );
  }
  return new GatewayError(
    502,
    "api_error",
    "The judgement provider could not answer.",
    "judgement_upstream_error",
  );
}

export class JudgementGateway {
  constructor(private readonly config: GatewayConfig) {}

  /**
   * Reserve against the account, call TypeSafe, settle on real token usage.
   *
   * Settlement always runs: on an upstream failure the reservation is
   * released rather than left holding credit, and a response that arrives
   * without usage is reconciled at the reserved ceiling rather than billed at
   * zero. Both are the same discipline `PortkeyProxy` applies.
   */
  async evaluate(
    principal: VerifiedPrincipal,
    body: unknown,
    idempotencyKey: string,
    requestHash: string,
  ): Promise<JudgementResult> {
    const request = validated(body);
    let backend = resolveDecisionBackend(this.config, request.model);
    compatible(request, backend);
    const loaders = await Promise.all((request.images ?? []).map(prepareRepresentationImage));
    const fallbackName = request.allow_fallback ? this.config.decisions?.fallback?.[backend.backend] : undefined;
    let fallbackBackend: ResolvedDecisionBackend | undefined;
    if (fallbackName && fallbackName !== backend.backend) {
      try {
        const candidate = resolveDecisionBackend(this.config, `judgement-${fallbackName}`);
        compatible(request, candidate); fallbackBackend = candidate;
      } catch (error) {
        if (!(error instanceof GatewayError)) throw error;
      }
    }
    let fallback: JudgementFallback | undefined;
    let requestId: string = crypto.randomUUID();
    const maxCostMicrousd = estimateMicrousd(request, backend) + (fallbackBackend ? estimateMicrousd(request, fallbackBackend) : 0);
    if (
      maxCostMicrousd >
      Math.min(
        principal.maxCostMicrousd,
        this.config.maxAllowedCostMicrousd ?? Number.MAX_SAFE_INTEGER,
      )
    ) {
      throw new GatewayError(
        402,
        "insufficient_quota",
        "The judgement exceeds the request budget.",
        "budget_exceeded",
      );
    }

    const reservation = await this.config.store.reserve({
      requestId,
      idempotencyKey,
      orgContext: principal.orgContext, agentContext: principal.agentContext, sessionVersion: principal.sessionVersion,
      accountId: principal.accountId,
      product: principal.product,
      feature: "judgement",
      alias: request.model ?? JUDGEMENT_ALIAS,
      maxCostMicrousd,
      pricingVersion: this.config.pricingVersion ?? "v1",
      requestHash,
    });
    if (reservation.status === "settled" && reservation.response) {
      const { model, answers, usage, fallback } = reservation.response;
      return { model, answers, usage, ...(fallback ? { fallback } : {}) } as JudgementResult;
    }
    if (reservation.status !== "reserved") {
      throw new GatewayError(
        409,
        "conflict_error",
        "This judgement request has already been submitted.",
        "idempotency_conflict",
      );
    }
    requestId = reservation.requestId;

    try {
      if (loaders.length) request.images = await Promise.all(loaders.map(load => load()));
    } catch (error) {
      await this.config.store.release({ requestId, reason: 'image_preparation_failed' });
      throw error;
    }

    try {
      await this.config.store.markDispatched({ requestId });
    } catch (error) {
      await this.config.store.release({
        requestId,
        reason: "dispatch_not_started",
      });
      throw error;
    }

    let response: Response;
    try {
      response = await this.#fetch(backend, request);
      // Only explicit overload rejections are eligible. Never repeat ambiguous delivery or accepted work.
      if ([429, 529].includes(response.status) && fallbackBackend) {
        fallback = { from: `judgement-${backend.backend}/${backend.model}`, to: `judgement-${fallbackBackend.backend}/${fallbackBackend.model}`, reason: `upstream_${response.status}` };
        backend = fallbackBackend;
        response = await this.#fetch(backend, request);
      }
    } catch {
      await this.config.store.reconcile({
        requestId,
        conservativeCostMicrousd: maxCostMicrousd,
        reason: "judgement_delivery_unknown",
      });
      throw new GatewayError(
        502,
        "api_error",
        "The judgement provider could not be reached.",
        "judgement_unreachable",
      );
    }

    if (!response.ok) {
      await this.config.store.release({
        requestId,
        reason: `upstream_${response.status}`,
      });
      throw upstreamFailure(response.status);
    }

    await this.config.store.markAccepted({ requestId });
    const payload: unknown = await boundedJson(response).catch(() => null);
    let answers: Record<string, unknown>;
    let model: string;
    try {
      if (!record(payload) || typeof payload.model !== 'string' || !payload.model.trim() || ['judgement', 'jev-latest', 'autojev'].includes(payload.model)) throw new Error('Missing concrete model identity');
      if (backend.backend === 'luna' && !/^gpt-6-luna(?:-|$)/.test(payload.model)) throw new Error('Unexpected Luna model');
      answers = backend.backend === 'luna' ? fromLunaAnswers(request.questions, payload.answers) : validateDecisionAnswers(request.questions, payload.answers);
      model = `judgement-${backend.backend}/${payload.model}`;
      if (fallback) fallback.to = model;
    } catch {
      await this.config.store.reconcile({ requestId, conservativeCostMicrousd: maxCostMicrousd, reason: 'invalid_upstream_response' });
      throw new GatewayError(502, 'api_error', 'The judgement provider returned invalid answers or model identity.', 'judgement_invalid_response');
    }
    const usage = normalizedUsage((payload as Record<string, unknown>).usage);
    const price = backend.price;
    const rawUsage = record(payload) && record(payload.usage) ? payload.usage : null;
    const seconds = rawUsage?.gpu_seconds;
    if (usage && backend.backend === "pplx" && typeof seconds === "number" && Number.isFinite(seconds) && seconds >= 0) usage.gpu_seconds = seconds;
    let cost: number | null = null;
    try {
      cost = price.unit === 'request' ? judgementCost(price, 1)
        : price.unit === 'gpu_second' ? (typeof seconds === 'number' && Number.isFinite(seconds) && seconds >= 0 ? judgementCost(price, seconds) : null)
        : usage ? judgementCost(price, usage.input_tokens!) : null;
    } catch { /* Invalid or overflowing reported usage is reconciled at the reservation ceiling. */ }
    if (cost === null) {
      // Answers without usage: bill conservatively at the ceiling rather than
      // give the call away, and mark it so it can be trued up out of band.
      await this.config.store.reconcile({
        requestId,
        conservativeCostMicrousd: maxCostMicrousd,
        reason: "judgement_usage_unavailable",
      });
    } else {
      const charged = Math.min(cost, maxCostMicrousd);
      await this.config.store.settleWithResponse({
        accountId: principal.accountId,
        orgContext: principal.orgContext,
        response: {
          id: requestId,
          object: "judgement",
          model,
          answers,
          ...(fallback ? { fallback } : {}),
          usage,
        },
        requestId,
        actualCostMicrousd: charged,
        providerAbsorbedMicrousd: Math.max(0, cost - charged),
        usage: usage ?? undefined,
      });
    }

    await this.#emitSettled(principal, {
      product: principal.product,
      alias: request.model ?? JUDGEMENT_ALIAS,
      backend: backend.backend,
      model,
      questions: Object.keys(request.questions).length,
      input_tokens: usage?.input_tokens ?? null,
      usage_complete: usage !== null,
      billed_usd:
        (cost === null ? maxCostMicrousd : Math.min(cost, maxCostMicrousd)) /
        1_000_000,
    });

    return { model, answers, usage, ...(fallback ? { fallback } : {}) };
  }

  models(): string[] {
    return ['judgement', 'judgement-vision', 'judgement-jev', 'judgement-luna', 'judgement-pplx'].filter(alias => {
      try { resolveDecisionBackend(this.config, alias); return true; } catch { return false; }
    });
  }

  #fetch(backend: ResolvedDecisionBackend, request: JudgementRequest): Promise<Response> {
    const origin = (backend.apiOrigin ?? (backend.backend === 'luna' ? 'https://api.openai.com' : DEFAULT_TYPESAFE_ORIGIN)).replace(/\/$/, '');
    return (this.config.fetch ?? fetch)(`${origin}${backend.backend === 'luna' ? '/v1/decisions' : '/v1/systemone'}`, {
      method: 'POST', redirect: 'error', signal: AbortSignal.timeout(backend.backend === 'pplx' ? 180_000 : 30_000),
      headers: { 'content-type': 'application/json', authorization: `Bearer ${backend.apiKey}` },
      body: JSON.stringify(backend.backend === 'luna' ? lunaBody(request) : {
        model: backend.model, state: request.state, questions: request.questions,
        ...(request.images?.length ? { images: request.images } : {}),
      }),
    });
  }

  /**
   * Analytics are keyed by an HMAC of the account id, never the id itself —
   * the same derivation `PortkeyProxy` uses, so judgement spend joins the
   * existing per-account series without putting a real identifier in PostHog.
   *
   * Keep the HMAC derivation aligned with PortkeyProxy so account spend joins
   * the same pseudonymous series without exposing the account identifier.
   */
  async #emitSettled(
    principal: VerifiedPrincipal,
    properties: Record<string, unknown>,
  ): Promise<void> {
    const telemetry = this.config.telemetry;
    if (!telemetry) return;
    try {
      const key = await crypto.subtle.importKey(
        "raw",
        new Uint8Array(this.config.pseudonymSecret).buffer as ArrayBuffer,
        { name: "HMAC", hash: "SHA-256" },
        false,
        ["sign"],
      );
      const digest = new Uint8Array(
        await crypto.subtle.sign(
          "HMAC",
          key,
          new TextEncoder().encode(principal.accountId),
        ),
      );
      await telemetry.capture(
        "judgement.settled",
        Buffer.from(digest).toString("base64url"),
        properties,
      );
    } catch {
      // Telemetry must never fail a settled judgement the writer already paid
      // for and is waiting on.
    }
  }
}

