/**
 * Typed value extraction (Cloudflare Clairic). Judgements answer questions about
 * a state; extraction reads values out of it: spans, numbers, dates, durations,
 * lists, and calibrated estimates and forecasts with p10/p90 intervals.
 */
export const EXTRACTION_MODELS = ['extraction', 'extraction-clairic'] as const;
export type ExtractionModel = (typeof EXTRACTION_MODELS)[number];

export const EXTRACTION_FIELD_TYPES = ['text', 'number', 'date', 'time', 'datetime', 'duration', 'list', 'estimate', 'forecast'] as const;
export type ExtractionFieldType = (typeof EXTRACTION_FIELD_TYPES)[number];

export const EXTRACTION_DURATION_UNITS = ['seconds', 'minutes', 'hours', 'days', 'weeks', 'months', 'years'] as const;
export const EXTRACTION_FORECAST_INTERVALS = ['step', 'minute', 'hour', 'day', 'week', 'month', 'quarter', 'year'] as const;

export interface ExtractionField {
  type: ExtractionFieldType;
  instructions?: string;
  /** Unit label; for durations one of EXTRACTION_DURATION_UNITS (default seconds). */
  unit?: string;
  /** Numbers and durations only. */
  integer?: boolean;
  /** 0–6; numbers, durations and number lists only. */
  decimals?: number;
  /** Required for list fields. */
  items?: 'text' | 'number' | 'date';
  /** Required for estimate and forecast: a number, or an ISO date for date estimates. */
  min?: number | string;
  max?: number | string;
  /** Estimate grid: a positive number (days for date estimates), or "month" / "year". */
  step?: number | 'month' | 'year';
  scale?: 'linear' | 'log';
  /** p_null above which `value` is null (default 0.5). */
  null_threshold?: number;
  /** Forecast only: 1–64 steps. */
  horizon?: number;
  /** Forecast only. */
  interval?: (typeof EXTRACTION_FORECAST_INTERVALS)[number];
}

export interface ExtractionRequest {
  model?: ExtractionModel;
  /** Text to read. Required unless images are sent. Text answers are spans of this string. */
  state?: string;
  fields: Record<string, ExtractionField>;
  /** At most four HTTPS or PNG/JPEG/WebP data URL images, placed before the state. */
  images?: string[];
  /** ISO date that anchors dates written without a year, and relative dates. */
  reference_date?: string;
  options?: { include_quantiles?: boolean; return_state_text?: boolean };
}

/**
 * One answer per field. `value` is null when the input does not determine it;
 * `guess` still carries the best candidate so callers can show a near miss.
 */
export interface ExtractionAnswer {
  type: ExtractionFieldType;
  value: unknown;
  guess?: unknown;
  /** Probability the value is absent from the input. */
  p_null?: number;
  confidence?: number;
  unit?: string;
  /** Text answers: [start, end) into the state. */
  span?: [number, number];
  /** List answers: one span per item, in input order. */
  spans?: [number, number][];
  mean?: unknown;
  median?: unknown;
  p10?: unknown;
  p90?: unknown;
  p_below?: number;
  p_above?: number;
  quantiles?: unknown[];
  /** Forecast only: one estimate per step. */
  steps?: unknown[];
}

export interface ExtractionUsage {
  input_tokens: number;
  output_tokens: number;
  state_tokens?: number;
  image_tokens?: number;
  schema_tokens?: number;
  passes?: number;
}

export interface ExtractionResult {
  /** `extraction-clairic/UPSTREAM_MODEL`. */
  model: string;
  answers: Record<string, ExtractionAnswer>;
  /** The state was longer than the model could read; answers cover the read prefix. */
  truncated: boolean;
  state_text?: string;
  usage: ExtractionUsage | null;
}

