import { EXTRACTION_DURATION_UNITS, EXTRACTION_FIELD_TYPES, EXTRACTION_FORECAST_INTERVALS, type ExtractionAnswer, type ExtractionField, type ExtractionRequest, type ExtractionResult, type ExtractionUsage } from '@notorganic/contracts';
import { judgementCost, validJudgementPrice, type JudgementPrice } from '@notorganic/core';
import { GatewayError } from './errors';
import type { GatewayConfig, VerifiedPrincipal } from './types';
import { record } from './decision-backends/wire';
import { boundedJson } from './representation-meter';
import { prepareRepresentationImage } from './representation-images';

export const EXTRACTION_ALIAS = 'extraction';
export const EXTRACTION_MAX_BODY_BYTES = 28_000_000;
// Published Workers AI rate: $0.10/M input tokens. Output is never billed.
export const DEFAULT_CLAIRIC_INPUT_TOKEN_MICROUSD = 0.1;
const CLAIRIC_MODEL = '@cf/cloudflare/clairic';
const MAX_FIELDS = 64;
const MAX_STATE_CHARS = 96_000;
const MAX_FIELD_CHARS = 32_000;
// Clairic splits fields that do not fit beside the state into parallel 8,192-token passes,
// and every pass re-reads the whole state, so input tokens grow with the pass count.
const PASS_TOKENS = 8_192;
const IMAGE_TOKENS = 8_192;
const MAX_IMAGE_BYTES = 4 * 1024 * 1024;
const MAX_IMAGES_BYTES = 8 * 1024 * 1024;

export interface ExtractionConfig { apiKey: string; accountId?: string; /** Full endpoint override, e.g. an AI Gateway URL. */ url?: string; price: JudgementPrice }

export function extractionConfigFromEnv(env: Record<string, string | undefined>): ExtractionConfig | undefined {
  const apiKey = env.CLOUDFLARE_AI_API_TOKEN?.trim();
  if (!apiKey) return undefined;
  const accountId = env.CLOUDFLARE_ACCOUNT_ID?.trim() || undefined;
  const url = env.CLAIRIC_URL?.trim() || undefined;
  if (!accountId && !url) throw new Error('CLOUDFLARE_AI_API_TOKEN requires CLOUDFLARE_ACCOUNT_ID or CLAIRIC_URL');
  if (url && !url.startsWith('https://')) throw new Error('CLAIRIC_URL must be https');
  const raw = env.EXTRACTION_CLAIRIC_PRICE_PER_INPUT_TOKEN_MICROUSD?.trim();
  const price: JudgementPrice = { unit: 'input_token', microusd: raw ? Number(raw) : DEFAULT_CLAIRIC_INPUT_TOKEN_MICROUSD };
  if (!validJudgementPrice(price)) throw new Error('Invalid EXTRACTION_CLAIRIC_PRICE_PER_INPUT_TOKEN_MICROUSD');
  return { apiKey, accountId, url, price };
}

function invalid(message: string, code = 'invalid_extraction_request', param?: string): never {
  throw new GatewayError(400, 'invalid_request_error', message, code, param);
}

const FIELD_NAME = /^[A-Za-z_][A-Za-z0-9_.\-]{0,63}$/;
const FIELD_KEYS = new Set(['type', 'instructions', 'unit', 'integer', 'decimals', 'items', 'min', 'max', 'step', 'scale', 'null_threshold', 'horizon', 'interval']);
const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;
const bound = (value: unknown) => (typeof value === 'number' && Number.isFinite(value)) || (typeof value === 'string' && ISO_DATE.test(value));

function validField(name: string, raw: unknown): ExtractionField {
  if (!FIELD_NAME.test(name)) invalid('Field names must match ^[A-Za-z_][A-Za-z0-9_.-]{0,63}$.', 'invalid_field_name', name);
  if (!record(raw) || Object.keys(raw).some(key => !FIELD_KEYS.has(key))) invalid('Each field is an object with known keys.', 'invalid_field', name);
  const f = raw as Record<string, unknown>;
  const type = f.type as ExtractionField['type'];
  if (!EXTRACTION_FIELD_TYPES.includes(type)) invalid(`Field type must be one of ${EXTRACTION_FIELD_TYPES.join(', ')}.`, 'invalid_field_type', name);
  if (f.instructions !== undefined && typeof f.instructions !== 'string') invalid('instructions must be a string.', 'invalid_field', name);
  if (f.unit !== undefined && (typeof f.unit !== 'string' || (type === 'duration' && !(EXTRACTION_DURATION_UNITS as readonly string[]).includes(f.unit)))) invalid('Use a string unit; durations take seconds through years.', 'invalid_field', name);
  if (f.integer !== undefined && (typeof f.integer !== 'boolean' || !['number', 'duration'].includes(type))) invalid('integer applies to numbers and durations.', 'invalid_field', name);
  if (f.decimals !== undefined && (!Number.isInteger(f.decimals) || (f.decimals as number) < 0 || (f.decimals as number) > 6)) invalid('decimals must be an integer from 0 to 6.', 'invalid_field', name);
  if (type === 'list' ? !['text', 'number', 'date'].includes(f.items as string) : f.items !== undefined) invalid('List fields require items: text, number or date.', 'invalid_field', name);
  const ranged = type === 'estimate' || type === 'forecast';
  if (ranged ? !bound(f.min) || !bound(f.max) : f.min !== undefined || f.max !== undefined) invalid('Estimates and forecasts require numeric or ISO date min and max.', 'invalid_field', name);
  if (ranged && typeof f.min === typeof f.max && (f.min as number | string) >= (f.max as number | string)) invalid('min must be below max.', 'invalid_field', name);
  if (f.step !== undefined && (type !== 'estimate' || !((typeof f.step === 'number' && f.step > 0 && Number.isFinite(f.step)) || f.step === 'month' || f.step === 'year'))) invalid('step applies to estimates: a positive number, month or year.', 'invalid_field', name);
  if (f.scale !== undefined && !['linear', 'log'].includes(f.scale as string)) invalid('scale is linear or log.', 'invalid_field', name);
  if (f.scale === 'log' && ((typeof f.min === 'number' && f.min <= 0) || typeof f.min === 'string')) invalid('Log scale needs a positive numeric min.', 'invalid_field', name);
  if (f.null_threshold !== undefined && (typeof f.null_threshold !== 'number' || !(f.null_threshold > 0 && f.null_threshold <= 1))) invalid('null_threshold must be in (0, 1].', 'invalid_field', name);
  if (type === 'forecast' ? !Number.isInteger(f.horizon) || (f.horizon as number) < 1 || (f.horizon as number) > 64 : f.horizon !== undefined) invalid('Forecasts require an integer horizon from 1 to 64.', 'invalid_field', name);
  if (type === 'forecast' ? !(EXTRACTION_FORECAST_INTERVALS as readonly string[]).includes(f.interval as string) : f.interval !== undefined) invalid(`Forecasts require interval: ${EXTRACTION_FORECAST_INTERVALS.join(', ')}.`, 'invalid_field', name);
  return f as unknown as ExtractionField;
}

export function validateExtractionRequest(body: unknown): ExtractionRequest {
  if (!record(body)) invalid('An extraction request body is required.', 'invalid_body');
  const { model, state, fields, images, reference_date, options, ...rest } = body;
  if (Object.keys(rest).length) invalid(`Unknown field: ${Object.keys(rest)[0]}.`, 'invalid_body');
  if (model !== undefined && model !== 'extraction' && model !== 'extraction-clairic') invalid('Use an extraction model alias.', 'invalid_model');
  if (state !== undefined && typeof state !== 'string') invalid('state must be a string.', 'invalid_state');
  if (images !== undefined && (!Array.isArray(images) || images.length > 4 || images.some(image => typeof image !== 'string'))) invalid('Use at most four HTTPS or data URL images.', 'invalid_images');
  if (!(state as string | undefined)?.length && !(images as string[] | undefined)?.length) invalid('Send non-empty state or at least one image.', 'invalid_state');
  if (((state as string | undefined)?.length ?? 0) > MAX_STATE_CHARS) invalid('The state is too large.', 'state_too_large');
  if (!record(fields) || !Object.keys(fields).length) invalid('Send at least one field.', 'invalid_fields');
  if (Object.keys(fields).length > MAX_FIELDS) invalid(`Send at most ${MAX_FIELDS} fields.`, 'too_many_fields');
  const normalized = Object.fromEntries(Object.entries(fields).map(([name, field]) => [name, validField(name, field)]));
  if (JSON.stringify(normalized).length > MAX_FIELD_CHARS) invalid('The field specs are too large.', 'fields_too_large');
  if (reference_date !== undefined && (typeof reference_date !== 'string' || !ISO_DATE.test(reference_date))) invalid('reference_date must be an ISO date.', 'invalid_reference_date');
  if (options !== undefined && (!record(options) || Object.entries(options).some(([key, value]) => !['include_quantiles', 'return_state_text'].includes(key) || typeof value !== 'boolean'))) invalid('options accepts boolean include_quantiles and return_state_text.', 'invalid_options');
  return {
    ...(model !== undefined ? { model: model as ExtractionRequest['model'] } : {}),
    ...(state !== undefined ? { state: state as string } : {}),
    fields: normalized,
    ...(images !== undefined ? { images: images as string[] } : {}),
    ...(reference_date !== undefined ? { reference_date: reference_date as string } : {}),
    ...(options !== undefined ? { options: options as ExtractionRequest['options'] } : {}),
  };
}

/** Reservation ceiling: every pass re-reads state and images, doubled for tokenizer headroom. */
export function extractionMaxInputTokens(request: ExtractionRequest): number {
  const stateTokens = Math.ceil((request.state?.length ?? 0) / 4) + (request.images?.length ?? 0) * IMAGE_TOKENS;
  const schemaTokens = Math.ceil(JSON.stringify(request.fields).length / 4) + Object.keys(request.fields).length * 16;
  const room = Math.max(1_024, PASS_TOKENS - Math.min(stateTokens, PASS_TOKENS - 1_024));
  const passes = Math.min(Object.keys(request.fields).length, Math.max(1, Math.ceil(schemaTokens / room)));
  return (passes * (stateTokens + 256) + schemaTokens) * 2;
}

const probability = (value: unknown) => typeof value === 'number' && Number.isFinite(value) && value >= 0 && value <= 1;
const span = (value: unknown, length: number | undefined) => Array.isArray(value) && value.length === 2 && value.every(n => Number.isInteger(n) && n >= 0) &&
  value[0] <= value[1] && (length === undefined || value[1] <= length);

/** Typed output guarantees the interface, not truth; reject anything that breaks the interface. */
export function validateExtractionAnswers(request: ExtractionRequest, raw: unknown): Record<string, ExtractionAnswer> {
  const names = Object.keys(request.fields);
  if (!record(raw) || Object.keys(raw).length !== names.length || names.some(name => !Object.hasOwn(raw, name))) throw new Error('Answer keys do not match fields');
  const length = request.images?.length ? undefined : request.state?.length;
  for (const name of names) {
    const a = raw[name], field = request.fields[name]!;
    if (!record(a) || a.type !== field.type || !Object.hasOwn(a, 'value')) throw new Error(`Invalid answer for ${name}`);
    for (const key of ['p_null', 'confidence', 'p_below', 'p_above'] as const) if (a[key] !== undefined && !probability(a[key])) throw new Error(`Invalid ${key} for ${name}`);
    if (field.type === 'text' && a.span !== undefined && !span(a.span, length)) throw new Error(`Invalid span for ${name}`);
    if (field.type === 'list') {
      if (a.value !== null && !Array.isArray(a.value)) throw new Error(`Invalid list for ${name}`);
      if (a.spans !== undefined && (!Array.isArray(a.spans) || !a.spans.every(s => span(s, length)))) throw new Error(`Invalid spans for ${name}`);
    }
    if ((field.type === 'number' || field.type === 'duration') && a.value !== null && !(typeof a.value === 'number' && Number.isFinite(a.value))) throw new Error(`Invalid number for ${name}`);
    if (field.type === 'forecast' && a.steps !== undefined && (!Array.isArray(a.steps) || a.steps.length !== field.horizon)) throw new Error(`Invalid forecast for ${name}`);
  }
  return raw as Record<string, ExtractionAnswer>;
}

function normalizedUsage(value: unknown): ExtractionUsage | null {
  if (!record(value)) return null;
  const count = (n: unknown) => typeof n === 'number' && Number.isSafeInteger(n) && n >= 0;
  if (!count(value.input_tokens) || !count(value.output_tokens)) return null;
  const usage: ExtractionUsage = { input_tokens: value.input_tokens as number, output_tokens: value.output_tokens as number };
  for (const key of ['state_tokens', 'image_tokens', 'schema_tokens', 'passes'] as const) if (count(value[key])) usage[key] = value[key] as number;
  return usage;
}

/** Upstream error text can echo the caller's own document. Never forward it. */
function upstreamFailure(status: number): GatewayError {
  if (status === 429) return new GatewayError(429, 'rate_limit_error', 'Extraction is rate limited upstream.', 'extraction_rate_limited');
  if (status === 401 || status === 403) return new GatewayError(503, 'api_error', 'Extraction is not configured correctly.', 'extraction_invalid_configuration');
  if (status === 400 || status === 413 || status === 422) return new GatewayError(400, 'invalid_request_error', 'The extraction request was rejected as malformed.', 'extraction_malformed');
  if (status === 503 || status === 529) return new GatewayError(503, 'api_error', 'Extraction is temporarily overloaded.', 'extraction_overloaded');
  return new GatewayError(502, 'api_error', 'The extraction provider could not answer.', 'extraction_upstream_error');
}

function imageBytes(dataUrl: string): number {
  const base64 = dataUrl.slice(dataUrl.indexOf(',') + 1);
  return Math.floor(base64.length * 3 / 4) - (base64.endsWith('==') ? 2 : base64.endsWith('=') ? 1 : 0);
}

export class ExtractionGateway {
  constructor(private readonly config: GatewayConfig) {}

  models(): string[] { return this.config.extraction ? ['extraction', 'extraction-clairic'] : []; }

  /** Reserve against the account, call Clairic, settle on reported input tokens; same discipline as JudgementGateway. */
  async extract(principal: VerifiedPrincipal, body: unknown, idempotencyKey: string, requestHash: string): Promise<ExtractionResult> {
    const request = validateExtractionRequest(body);
    const configured = this.config.extraction;
    if (!configured) throw new GatewayError(503, 'api_error', 'This extraction model is not configured with credentials and a price.', 'model_unavailable');
    const loaders = await Promise.all((request.images ?? []).map(prepareRepresentationImage));
    const maxCostMicrousd = Math.max(50, judgementCost(configured.price, extractionMaxInputTokens(request)));
    if (maxCostMicrousd > Math.min(principal.maxCostMicrousd, this.config.maxAllowedCostMicrousd ?? Number.MAX_SAFE_INTEGER)) {
      throw new GatewayError(402, 'insufficient_quota', 'The extraction exceeds the request budget.', 'budget_exceeded');
    }
    const alias = request.model ?? EXTRACTION_ALIAS;
    const reservation = await this.config.store.reserve({
      requestId: crypto.randomUUID(), idempotencyKey,
      orgContext: principal.orgContext, agentContext: principal.agentContext, sessionVersion: principal.sessionVersion,
      accountId: principal.accountId, product: principal.product, feature: 'extraction', alias,
      maxCostMicrousd, pricingVersion: this.config.pricingVersion ?? 'v1', requestHash,
    });
    if (reservation.status === 'settled' && reservation.response) {
      const { model, answers, truncated, state_text, usage } = reservation.response;
      return { model, answers, truncated, ...(state_text !== undefined ? { state_text } : {}), usage } as ExtractionResult;
    }
    if (reservation.status !== 'reserved') throw new GatewayError(409, 'conflict_error', 'This extraction request has already been submitted.', 'idempotency_conflict');
    const requestId = reservation.requestId;

    try {
      if (loaders.length) {
        request.images = await Promise.all(loaders.map(load => load()));
        const sizes = request.images.map(imageBytes);
        if (sizes.some(size => size > MAX_IMAGE_BYTES) || sizes.reduce((a, b) => a + b, 0) > MAX_IMAGES_BYTES) {
          throw new GatewayError(413, 'invalid_request_error', 'Extraction images are limited to 4 MiB each and 8 MiB together.', 'input_too_large');
        }
      }
      await this.config.store.markDispatched({ requestId });
    } catch (error) {
      await this.config.store.release({ requestId, reason: 'dispatch_not_started' });
      throw error;
    }

    let response: Response;
    try {
      response = await this.#fetch(configured, request);
    } catch {
      await this.config.store.reconcile({ requestId, conservativeCostMicrousd: maxCostMicrousd, reason: 'extraction_delivery_unknown' });
      throw new GatewayError(502, 'api_error', 'The extraction provider could not be reached.', 'extraction_unreachable');
    }
    if (!response.ok) {
      await this.config.store.release({ requestId, reason: `upstream_${response.status}` });
      throw upstreamFailure(response.status);
    }

    await this.config.store.markAccepted({ requestId });
    let result: Omit<ExtractionResult, 'usage'>;
    let usage: ExtractionUsage | null;
    try {
      const envelope = await boundedJson(response, 4_000_000);
      // The REST API wraps model output in { result, success }; AI Gateway and bindings may not.
      const payload: Record<string, unknown> = record(envelope.result) ? envelope.result : envelope;
      if (typeof payload.model !== 'string' || !/^(?:clairic|@cf\/cloudflare\/clairic)(?:[-@:.][\w.-]+)?$/.test(payload.model)) throw new Error('Unexpected model');
      if (typeof payload.truncated !== 'boolean') throw new Error('Missing truncated');
      result = {
        model: `extraction-clairic/${payload.model.replace(/^@cf\/cloudflare\//, '')}`,
        answers: validateExtractionAnswers(request, payload.answers),
        truncated: payload.truncated,
        ...(request.options?.return_state_text && typeof payload.state_text === 'string' ? { state_text: payload.state_text } : {}),
      };
      usage = normalizedUsage(payload.usage);
    } catch {
      await this.config.store.reconcile({ requestId, conservativeCostMicrousd: maxCostMicrousd, reason: 'invalid_upstream_response' });
      throw new GatewayError(502, 'api_error', 'The extraction provider returned invalid answers or model identity.', 'extraction_invalid_response');
    }

    let cost: number | null = null;
    try { cost = usage ? judgementCost(configured.price, usage.input_tokens) : null; } catch { /* Overflowing usage reconciles at the ceiling. */ }
    if (cost === null) {
      await this.config.store.reconcile({ requestId, conservativeCostMicrousd: maxCostMicrousd, reason: 'extraction_usage_unavailable' });
    } else {
      const charged = Math.min(cost, maxCostMicrousd);
      await this.config.store.settleWithResponse({
        accountId: principal.accountId, orgContext: principal.orgContext,
        response: { id: requestId, object: 'extraction', ...result, usage },
        requestId, actualCostMicrousd: charged, providerAbsorbedMicrousd: Math.max(0, cost - charged),
        usage: usage ? { input_tokens: usage.input_tokens, output_tokens: usage.output_tokens } : undefined,
      });
    }
    await this.#emitSettled(principal, {
      product: principal.product, alias, model: result.model,
      fields: Object.keys(request.fields).length, images: request.images?.length ?? 0, truncated: result.truncated,
      input_tokens: usage?.input_tokens ?? null, passes: usage?.passes ?? null, usage_complete: usage !== null,
      billed_usd: (cost === null ? maxCostMicrousd : Math.min(cost, maxCostMicrousd)) / 1_000_000,
    });
    return { ...result, usage };
  }

  #fetch(configured: ExtractionConfig, request: ExtractionRequest): Promise<Response> {
    const url = configured.url ?? `https://api.cloudflare.com/client/v4/accounts/${encodeURIComponent(configured.accountId!)}/ai/run/${CLAIRIC_MODEL}`;
    return (this.config.fetch ?? fetch)(url, {
      method: 'POST', redirect: 'error', signal: AbortSignal.timeout(30_000),
      headers: { 'content-type': 'application/json', authorization: `Bearer ${configured.apiKey}` },
      body: JSON.stringify({
        model: 'clairic', state: request.state ?? '', fields: request.fields,
        ...(request.images?.length ? { images: request.images } : {}),
        ...(request.reference_date ? { reference_date: request.reference_date } : {}),
        ...(request.options ? { options: request.options } : {}),
      }),
    });
  }

  /** Same HMAC pseudonym as JudgementGateway, so extraction spend joins the per-account series. */
  async #emitSettled(principal: VerifiedPrincipal, properties: Record<string, unknown>): Promise<void> {
    const telemetry = this.config.telemetry;
    if (!telemetry) return;
    try {
      const key = await crypto.subtle.importKey('raw', new Uint8Array(this.config.pseudonymSecret).buffer as ArrayBuffer, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
      const digest = new Uint8Array(await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(principal.accountId)));
      await telemetry.capture('extraction.settled', Buffer.from(digest).toString('base64url'), properties);
    } catch {
      // Telemetry must never fail an extraction the caller already paid for.
    }
  }
}

