import { describe, expect, mock, test } from "bun:test";
import { ExtractionGateway, extractionConfigFromEnv, extractionMaxInputTokens, validateExtractionRequest } from "./extraction";
import type { ProviderStore, VerifiedPrincipal } from "./types";

const principal: VerifiedPrincipal = {
  accountId: "did:plc:alice", product: "twyne",
  scopes: new Set(["extraction:run"]), jkt: "test-jkt",
  maxCostMicrousd: 100_000, tokenType: "user", environment: "browser",
};

const state = "Invoice INV-2291 from Northwind Supply, issued 2026-09-02, net 30. Contact: Dana Ruiz, Priya Shah.";
const fields = {
  invoice_number: { type: "text" },
  due_date: { type: "date", instructions: "Issue date plus the net payment days" },
  contacts: { type: "list", items: "text" },
  po_number: { type: "text" },
  days_to_pay: { type: "estimate", min: 0, max: 120, step: 1 },
};
// Shape copied from the published Clairic response, wrapped as the REST API returns it.
const answers = {
  invoice_number: { type: "text", p_null: 3.8e-10, span: [8, 16], guess: "INV-2291", confidence: 1, value: "INV-2291" },
  due_date: { type: "date", p_null: 1e-6, guess: "2026-10-02", confidence: 0.99, value: "2026-10-02" },
