  const requests: Request[] = [];
  const events: Array<Record<string, unknown> | undefined> = [];
  const store = { getAccount: async () => ({ account: null }),
    reserve: mock(async ({ requestId }: { requestId: string }) => ({ requestId, status: "reserved" as const })),
    markDispatched: mock(async () => {}), markAccepted: mock(async () => {}),
    settleWithResponse: mock(async (_: unknown) => {}), release: mock(async () => {}),
    reconcile: mock(async () => {}),
  };
  const gateway = new ExtractionGateway({
    store: store as unknown as ProviderStore, portkeyApiKey: "unused",
    gatewayIssuer: "https://gateway.test", gatewayAudience: "notorganic",
    gatewaySigningPrivateJwk: {}, gatewaySigningPublicJwk: {},
    pseudonymSecret: new Uint8Array(32),
    extraction: { apiKey: "cf-token", accountId: "acct", price: { unit: "input_token", microusd: 0.1 } },
    telemetry: { enabled: true, capture: async (_event, _id, properties) => { events.push(properties); } },
    fetch: async (input, init) => {
      requests.push(new Request(input, init));
      return Response.json(payload, { status });
