import { publishFrenchLanding } from "./localized-landing";
import { cp, mkdir, rm } from "node:fs/promises";
import { resolve } from "node:path";

/** Compose the public site without loading application code or credentials. */
export async function buildPublicSite(root: string, output: string, includePortal = false): Promise<void> {
  await rm(output, { recursive: true, force: true });
  await mkdir(output, { recursive: true });
  await cp(resolve(root, "apps/landing"), output, { recursive: true });
  await publishFrenchLanding(root, output);
  await cp(resolve(root, "apps/docs"), resolve(output, "developers"), { recursive: true });
  if (includePortal) await cp(resolve(root, "dist/portal"), resolve(output, "identity"), { recursive: true });
}

if (import.meta.main) {
  const root = resolve(import.meta.dir, "..");
  const output = process.argv.includes("--landing") ? "dist/landing" : "dist/public";
  const build = Bun.spawn(["bunx", "--no-install", "vite", "build", "--config", "apps/portal/vite.config.ts"], { cwd: root, stdout: "inherit", stderr: "inherit" });
  if (await build.exited !== 0) throw new Error("Portal frontend build failed.");
  await buildPublicSite(root, resolve(root, output), true);
  console.log(`Built public website, docs, and identity frontend in ${output}.`);
}

